def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    # Recolour every non-background cell lying an even distance from the right edge.
    for x in range(W):
        if (W - 1 - x) % 2 == 0:
            for y in range(H):
                if g[y, x] != bg:
                    out[y, x] = 3
    emit(out, "Every grey cell in a column at even distance from the right edge "
              "(last column, then every second one leftward) becomes green.")
    return out
